# Function to check if a number is prime
def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

# Function to find the products of exactly three distinct primes that sum to a given value
def find_products_of_primes(sum_of_primes):
    products = []
    primes = [i for i in range(2, sum_of_primes) if is_prime(i)]
    for i in range(len(primes)):
        for j in range(i + 1, len(primes)):
            for k in range(j + 1, len(primes)):
                if primes[i] + primes[j] + primes[k] == sum_of_primes:
                    product = primes[i] * primes[j] * primes[k]
                    products.append(product)
    return products

